import sqlite3

db=sqlite3.connect(":memory:");db.executescript("""
CREATE TABLE customers(id INTEGER PRIMARY KEY,name TEXT);
CREATE TABLE orders(order_id INTEGER,customer_id INTEGER,amount REAL);
INSERT INTO customers VALUES(1,'Ada'),(2,'Ben'),(3,'Chen');
INSERT INTO orders VALUES(10,1,50),(11,1,70),(12,4,30);
""")
queries={
"INNER":"SELECT * FROM customers c INNER JOIN orders o ON c.id=o.customer_id",
"LEFT":"SELECT * FROM customers c LEFT JOIN orders o ON c.id=o.customer_id",
"FULL":"SELECT * FROM customers c FULL OUTER JOIN orders o ON c.id=o.customer_id"}
for name,q in queries.items():
    try: print(name,db.execute(q).fetchall())
    except sqlite3.OperationalError: print(name,"FULL may require newer SQLite")
print("customers without orders",db.execute("SELECT c.* FROM customers c LEFT JOIN orders o ON c.id=o.customer_id WHERE o.order_id IS NULL").fetchall())

## MATLAB — פונקציות רלוונטיות

| פונקציה / כלי | תפקיד |
|---|---|
| `innerjoin` | INNER על tables |
| `outerjoin` | LEFT/RIGHT/FULL לפי MergeKeys/Type |
| `join` | חיבור tables לפי keys |



```matlab
clear;customers=table([1;2;3],["Ada";"Ben";"Chen"],'VariableNames',{'id','name'});
orders=table([10;11;12],[1;1;4],[50;70;30],'VariableNames',{'order_id','id','amount'});
disp(innerjoin(customers,orders,'Keys','id'));
disp(outerjoin(customers,orders,'Keys','id','MergeKeys',true,'Type','left'));
```
